from typing import Any, Dict, List
from ranking import bm25_rank, dense_rank, hybrid_rank
from utils_types import BudgetConfig
def normalize_documents(results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
normed = []
for r in results:
normed.append({
"query": r.get("query", ""),
"rank": r.get("rank", 0),
"evidence": r.get("evidence", ""),
})
return normed
def dedupe_results(results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
seen = set()
out = []
for r in results:
key = (r.get("query", ""), r.get("evidence", ""))
if key not in seen:
seen.add(key)
out.append(r)
return out
def rerank_results(results: List[Dict[str, Any]], strategy: str = "relevance_then_recency") -> List[Dict[str, Any]]:
return sorted(results, key=lambda r: r.get("rank", 0))
def fuse_sources(results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
return sorted(results, key=lambda r: r.get("query", ""))
def truncate_by_budget(results: List[Dict[str, Any]], config: BudgetConfig) -> List[Dict[str, Any]]:
if len(results) <= config.max_rag_items:
return results
return results[-config.max_rag_items:]
def apply_ranker(results: List[Dict[str, Any]], strategy: str | None = None) -> List[Dict[str, Any]]:
if strategy == "bm25":
return bm25_rank(results)
if strategy == "dense":
return dense_rank(results)
if strategy == "hybrid":
return hybrid_rank(results)
return rerank_results(results, strategy or "relevance_then_recency")
"""Deterministic evidence fusion helpers."""
from typing import Any, Dict, Iterable, List
def fuse_results(list_of_sources: Iterable[List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
merged: List[Dict[str, Any]] = []
for source in list_of_sources:
for item in source:
merged.append(dict(item))
return sorted(merged, key=lambda r: (r.get("query", ""), r.get("rank", 0)))
def _stable_dense_score(query: str) -> int:
digest = hashlib.sha256(query.encode("utf-8")).hexdigest()
return int(digest, 16) % 100
def _order_and_rank(items: List[Dict[str, Any]], score_key: str) -> List[Dict[str, Any]]:
ranked = []
for item in items:
ranked.append(dict(item))
ranked.sort(
key=lambda r: (
-r.get(score_key, 0),
r.get("query", ""),
r.get("evidence", ""),
)
)
for idx, entry in enumerate(ranked):
entry["rank"] = idx + 1
return ranked
def bm25_rank(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
scored: List[Dict[str, Any]] = []
for item in items:
evidence = str(item.get("evidence", ""))
score = len(evidence)
scored.append({**item, "bm25_score": score, "score": score})
return _order_and_rank(scored, "score")
def dense_rank(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
scored: List[Dict[str, Any]] = []
for item in items:
query = str(item.get("query", ""))
score = _stable_dense_score(query)
scored.append({**item, "dense_score": score, "score": score})
return _order_and_rank(scored, "score")
def hybrid_rank(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
scored: List[Dict[str, Any]] = []
for item in items:
evidence = str(item.get("evidence", ""))
query = str(item.get("query", ""))
bm25_score = len(evidence)
dense_score = _stable_dense_score(query)
score = (bm25_score + dense_score) / 2
scored.append(
{
**item,
"bm25_score": bm25_score,
"dense_score": dense_score,
"hybrid_score": score,
"score": score,
}
)
return _order_and_rank(scored, "score")
